// [perf patch] remember what was last reported to the CET side
public let kbmReportedToCET: Bool;
public let kbmLastReported: Bool;
public let kbmReportCountdown: Int32;

// [perf patch] read the keyboard/controller state once, and only push it to the CET side when it
// changes (re-sent every 300 inputs as a safety net) instead of on every single input event
let kbmNow: Bool = this.player.PlayerLastUsedKBM();
this.kbmReportCountdown -= 1;
if !this.kbmReportedToCET || NotEquals(kbmNow, this.kbmLastReported) || this.kbmReportCountdown <= 0 {
  CustomQuickslotsGlobalInputListener.SetLastUsedKBM(kbmNow, this.player.gracePeriodOver);
  if this.player.gracePeriodOver {
    this.kbmReportedToCET = true;
    this.kbmLastReported = kbmNow;
    this.kbmReportCountdown = 300;
  }
}

