// Untrack Quest Ultimate (QuestTrackingToggle) - per-frame cost patch (patch 2026-11-01).
// The CET mod observed PlayerPuppet.OnAction and ScriptedPuppet.OnCommunicationEvent. Those run for every
// input action (mouse and stick axes, many per frame) and every NPC communication event, and every call
// crossed into Lua even though the mod only acts on button actions, LeanFB, and its own untrack request.
// These wrappers pass only those calls on, to two empty methods that the patched init.lua observes
// instead. Same order as before (input before the game handles it, the request after). Needs the patched
// init.lua; remove both files together.

@wrapMethod(PlayerPuppet)
protected cb func OnAction(action: ListenerAction, consumer: ListenerActionConsumer) -> Bool {
  if ListenerAction.IsButton(action) || ListenerAction.IsAction(action, n"LeanFB") {
    this.QTT_OnTrackedAction(action, consumer);
  }
  return wrappedMethod(action, consumer);
}

@addMethod(PlayerPuppet)
public func QTT_OnTrackedAction(action: ListenerAction, consumer: ListenerActionConsumer) -> Void {}

@wrapMethod(ScriptedPuppet)
protected cb func OnCommunicationEvent(evt: ref<CommunicationEvent>) -> Bool {
  let result: Bool = wrappedMethod(evt);
  if Equals(evt.name, n"mod_custom_untrack_quest_request_event") && Equals(evt.sender, this.GetEntityID()) {
    this.QTT_OnUntrackRequest(evt);
  }
  return result;
}

@addMethod(ScriptedPuppet)
public func QTT_OnUntrackRequest(evt: ref<CommunicationEvent>) -> Void {}
